FILES={}
def write(folder,name,text):
 d=P/folder;d.mkdir(exist_ok=True);f=d/name;f.write_text(text.strip()+'\n');FILES[name]=str(f.relative_to(P));return f
def rows(folder,name,header,data=()):
 d=P/folder;d.mkdir(exist_ok=True);f=d/name
 with f.open('w',newline='') as h:w=csv.writer(h);w.writerow(header);w.writerows(data)
 FILES[name]=str(f.relative_to(P));return f
