write(T,'filing_demo.html',r'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Filing preparation teaching simulation</title><style>body{font:18px system-ui;max-width:850px;margin:45px auto;color:#1c3144}h1{font-size:30px}label{display:block;margin:20px 0}input,select,button{font:inherit;padding:9px}input{width:250px}button{margin-right:12px}#result{white-space:pre-wrap;border-top:1px solid #ccc;padding-top:20px}.notice{font-weight:bold;color:#ad371d}</style><h1>Filing preparation teaching simulation</h1><p class="notice">Fictional local exercise. No URA connection, tax calculation, declaration or payment.</p><p>Use M-01, 2026-09 and net teaching sales of UGX 98,000,000. Review evidence before a mock action.</p><label>Case <input id="case" value="M-01"></label><label>Period <input id="period" value="2026-09"></label><label>Net teaching sales in UGX <input id="sales" type="number"></label><label>Evidence status <select id="evidence"><option value="missing">Required evidence missing</option><option value="ready">Teaching evidence checked</option></select></label><label>Reviewer decision <select id="review"><option value="pending">Pending</option><option value="approve">Approve mock action</option><option value="decline">Decline</option></select></label><button onclick="run(false)">Validate</button><button onclick="run(true)">Run mock action</button><div id="result" aria-live="polite"></div><script>function run(action){let out=document.getElementById('result');let v=id=>document.getElementById(id).value;let errors=[];if(v('case')!=='M-01')errors.push('Unknown teaching case.');if(v('period')!=='2026-09')errors.push('Check the teaching period.');if(v('sales')===''||Number(v('sales'))!==98000000)errors.push('Sales must match the checked teaching reconciliation.');if(v('evidence')!=='ready')errors.push('Required teaching evidence remains unresolved.');if(errors.length){out.textContent='HELD\n'+errors.join('\n');return;}if(!action){out.textContent='Structural teaching checks passed. This does not establish tax treatment or submission authority.';return;}if(v('review')!=='approve'){out.textContent='STOPPED\nNo mock action: reviewer decision is '+v('review');return;}out.textContent='MOCK ACKNOWLEDGEMENT M-01-DEMO\nFictional local action only. No URA submission occurred.\nPeriod '+v('period')+'; teaching sales UGX '+Number(v('sales')).toLocaleString();}</script></html>''')
write(C,'Verified Authority Example.txt',"""CHECKED COURT-TEXT EXAMPLE\nGoal Relief Development Organisation v Uganda Revenue Authority, Civil Appeal 50 of 2023, [2024] UGCommC 272, 19 August 2024.\nProposition: in explaining appeal scope, the court cites section 27(2) of the Tax Appeals Tribunal Act.\nShort exact quotation: An appeal to the High Court may be made on questions of law only.\nPinpoint: printed page 3, lines 24 to 27.\nThe full judgment text was inspected in the court-document reproduction at SheriaHub on 26 October 2026. Use the source URL in Public Sources.txt. Distinguish the reproduced judgment from publisher commentary. Verify current law and subsequent treatment before applying it. This is a research-method example and establishes no conclusion about Victoria’s fictional circumstances.\n""")
